// Writes src/data/studioProductImages.ts from the files in public/images/products/ai/.
// Runs automatically at the start of `pnpm build`.
import fs from 'node:fs';
import path from 'node:path';
import { ROOT, readStudioImages } from './lib/productImages.mjs';

const images = readStudioImages();
const lines = [
  '// Generated by scripts/build_studio_image_map.mjs. Do not edit by hand.',
  '// White-background representative product images in public/images/products/ai/.',
  'export const studioProductImages: Record<string, string> = {',
  ...Object.entries(images).map(([id, url]) => `  '${id}': '${url}',`),
  '};',
  '',
];
fs.writeFileSync(path.join(ROOT, 'src/data/studioProductImages.ts'), lines.join('\n'), 'utf-8');
console.log(`Studio image map: ${Object.keys(images).length} items`);
